def count_primes(n: int) -> int:
    """Number of primes strictly less than n. 0 <= n <= 5*10^6."""
    if n <= 2:
        return 0
    # Sieve of Eratosthenes up to n-1
    size = n
    is_prime = bytearray(b'\x01') * size
    is_prime[0:2] = b'\x00\x00'          # 0 and 1 are not prime
    limit = int(n ** 0.5) + 1
    for p in range(2, limit):
        if is_prime[p]:
            step = p
            start = p * p
            is_prime[start:size:step] = b'\x00' * ((size - start - 1) // step + 1)
    return sum(is_prime[:n])
